<?php if(!isset($db)){http_response_code(403);exit;}
$archivoPagos = ($_GET['registro'] ?? '') === 'historial';
$condicionPagos = $archivoPagos ? "s.tipo_pago='Propio' AND (s.pago_estado='pagado' OR COALESCE(s.pago_verificado_por,'')<>'')" : "s.tipo_pago='Propio' AND s.pago_estado='en revisión' AND s.estado<>'Rechazado' AND COALESCE(s.comprobante_ruta,'')<>''";
$q=$db->prepare("SELECT s.*,i.nombre_ingenios,COALESCE(p.nombre,c.nombre_cursos) curso_nombre FROM solicitudes_inscripcion s LEFT JOIN ingenios i ON i.id=s.ingenio_id LEFT JOIN planificacion_cursos p ON p.id=s.planificacion_id LEFT JOIN cursos c ON c.id=s.curso_id WHERE ".$condicionPagos."".($planFiltro?' AND s.planificacion_id=?':'').' ORDER BY s.pago_validado_en,s.id_solicitud');$q->execute($planFiltro?[$planFiltro]:[]);
$pendientes=array_filter($q->fetchAll(PDO::FETCH_ASSOC),static function($s)use($limitado,$busqueda){return ($limitado===null||cengi_texto_normalizado($s['nombre_ingenios'])===cengi_texto_normalizado($limitado))&&($busqueda===''||strpos(cengi_texto_normalizado($s['nombre_participante'].' '.$s['curso_nombre'].' '.$s['boleta']),cengi_texto_normalizado($busqueda))!==false);});
// Misma persona (por CUI) ya inscrita en otro curso: se avisa para no confundir inscripciones.
$otrosCursos = [];
if (!$archivoPagos && $pendientes) {
    $qo = $db->prepare("SELECT COALESCE(p.nombre, c.nombre_cursos) FROM solicitudes_inscripcion s LEFT JOIN planificacion_cursos p ON p.id = s.planificacion_id LEFT JOIN cursos c ON c.id = s.curso_id WHERE s.cui_participante = ? AND s.id_solicitud <> ? AND s.estado = 'Aprobado'");
    foreach ($pendientes as $pe) {
        if ((string) $pe['cui_participante'] === '') { continue; }
        $qo->execute([$pe['cui_participante'], $pe['id_solicitud']]);
        $otrosCursos[$pe['id_solicitud']] = $qo->fetchAll(PDO::FETCH_COLUMN);
    }
}
?>
<?php cengi_pagos_nav($db, $archivoPagos ? 'historial' : 'boletas'); ?>
<section class="pp-card pp-revision">
<div class="pp-card-head"><div><h3><?php if ($archivoPagos): ?>Historial de pagos y comprobantes<?php else: ?>Boletas por validar · Administración<?php endif; ?> <span class="pp-revision-count"><?= count($pendientes) ?></span></h3><?php if ($archivoPagos): ?><p class="pp-sub">Pagos propios ya validados por Administración: boleta, forma de pago, quién verificó y el comprobante. La persona ya está en Inscritos.</p><?php else: ?><p class="pp-sub">Boletas que subió el participante en el formulario o que cargó Capacitación. Al validar, el pago queda confirmado, la persona pasa a Inscritos y el pago se guarda en Historial de pagos.</p><?php endif; ?></div></div>
<form method="get" class="pp-toolbar pp-revision-search"><input type="hidden" name="vista" value="pagos"><input type="hidden" name="registro" value="<?= $archivoPagos ? 'historial' : '' ?>"><input type="hidden" name="plan" value="<?= (int)$planFiltro ?>"><label for="ppRevisionBuscar">Buscar participante, curso o boleta</label><div class="pp-revision-search-row"><input type="search" id="ppRevisionBuscar" name="q" value="<?= cengi_pp_h($busqueda) ?>" placeholder="Nombre, curso o número de boleta"><button class="btn btn-primary"><span class="glyphicon glyphicon-search" aria-hidden="true"></span> Buscar</button></div></form>
<div class="pp-table-wrap"><table class="cengi-org-table"><thead><tr><th>Participante / curso</th><th>Depósito</th><th>Boleta cargada por</th><th>Observación</th><th>Verificación administrativa</th></tr></thead><tbody>
<?php foreach($pendientes as $s): ?><tr><td><strong><?= cengi_pp_h($s['nombre_participante']) ?></strong><span class="pp-sub"><?= cengi_pp_h($s['curso_nombre']) ?></span><span class="pp-sub">Inscripción #<?= (int) $s['id_solicitud'] ?><?= $s['cui_participante'] ? ' · CUI ' . cengi_pp_h($s['cui_participante']) : '' ?></span><?php if (!$archivoPagos && !empty($otrosCursos[$s['id_solicitud']])): ?><span class="pp-chip is-ok" title="Inscrito en: <?= cengi_pp_h(implode(', ', $otrosCursos[$s['id_solicitud']])) ?>">Ya inscrito en otro curso</span><?php endif; ?></td><td><?= cengi_ins_dinero($s['monto_comprobante'],$s['moneda']) ?><span class="pp-sub"><?= cengi_pp_h($s['boleta'].' · '.$s['pago_fecha']) ?></span><?php if (!empty($s['comprobante_ruta'])): ?><a target="_blank" rel="noopener" href="comprobante_inscripcion.php?s=<?= (int)$s['id_solicitud'] ?>">Ver constancia</a><?php else: ?><span class="pp-sub">Sin archivo registrado</span><?php endif; ?></td><td><?= cengi_pp_h($s['pago_validado_por'] ?: ($archivoPagos ? $s['pago_verificado_por'] : 'Participante (formulario)')) ?><span class="pp-sub"><?= cengi_pp_h($s['pago_validado_rol']) ?></span><span class="pp-sub"><?= cengi_pp_h($s['pago_validado_en']) ?></span></td><td><?= cengi_pp_h($s['pago_validacion_evidencia']) ?><span class="pp-sub"><?= cengi_pp_h($s['pago_nota']) ?></span></td><td><?php if($archivoPagos): ?><strong><?= cengi_pp_h($s['pago_estado']) ?></strong><span class="pp-sub">Verificó: <?= cengi_pp_h($s['pago_verificado_por']) ?></span><span class="pp-sub"><?= cengi_pp_h($s['pago_verificado_en'] ?? '') ?></span><?php elseif(cengi_ins_puede_validar_pagos()): ?><a class="btn btn-primary btn-sm" href="interesado_validar_pago.php?id=<?= (int)$s['id_solicitud'] ?>&amp;via=administracion">Validar pago</a><?php else: ?>Pendiente de Administración<?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$pendientes): ?><tr><td colspan="5"><?= $archivoPagos ? 'No hay registros en el historial con estos filtros.' : 'No hay pagos pendientes de verificación.' ?></td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
